const REPORT_URL = "https://app.powerbi.com/groups/me/reports/204c2a7f-5c43-4658-a975-908fc8c580b8/436f3d97afe85a1c7217";

const f = $('On form submission').first().json;
const est = $('Leer estado_mes').all().map(i => i.json);
const cat = $('Leer categoria_mes').all().map(i => i.json)
  .map(r => ({ ...r, categoria: r.categoria || 'sin_categoria' }));

// --- Lo que eligió el usuario ---
const estadoSel = String(f['Estado'] ?? '').trim().toUpperCase();
const anioSel = f['Año'] || 'Todos';
const catSel = String(f['Categoría'] ?? '').trim().toLowerCase();
const tipo = f['Tipo de análisis'];
const todosKpis = ['Ventas BRL','Ventas USD','Órdenes','Ticket promedio','% entregas tarde',
                   'Días de entrega','Calificación promedio','% reseñas negativas'];
let kpisSel = f['KPIs'];
if (!Array.isArray(kpisSel)) kpisSel = kpisSel ? [kpisSel] : [];
if (!kpisSel.length) kpisSel = todosKpis;

// --- Utilidades ---
const num = v => {
  if (typeof v === 'number') return v;
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(String(v).replace(',', '.'));
  return isNaN(n) ? 0 : n;
};
const camposEst = ['ventas','ventas_usd','flete','ordenes','entregadas','entregas_tarde',
                   'dias_entrega_total','resenas','suma_calificacion','resenas_negativas'];
const camposCat = ['ventas','ventas_usd','articulos','ordenes','resenas',
                   'suma_calificacion','resenas_negativas'];

const sumar = (rows, campos) => {
  const t = Object.fromEntries(campos.map(c => [c, 0]));
  for (const r of rows) for (const c of campos) t[c] += num(r[c]);
  return t;
};
const div = (a, b, d = 2) => (b ? +(a / b).toFixed(d) : null);
const kpis = t => ({
  'Ventas BRL': +t.ventas.toFixed(2),
  'Ventas USD': +t.ventas_usd.toFixed(2),
  'Órdenes': t.ordenes,
  'Ticket promedio': div(t.ventas, t.ordenes),
  '% entregas tarde': t.entregadas !== undefined ? div(100 * t.entregas_tarde, t.entregadas, 1) : null,
  'Días de entrega': t.entregadas !== undefined ? div(t.dias_entrega_total, t.entregadas, 1) : null,
  'Calificación promedio': div(t.suma_calificacion, t.resenas),
  '% reseñas negativas': div(100 * t.resenas_negativas, t.resenas, 1),
});
const elegir = k => Object.fromEntries(Object.entries(k).filter(([n]) => kpisSel.includes(n)));
const agrupar = (rows, clave) => rows.reduce((g, r) => ((g[r[clave]] ??= []).push(r), g), {});

// --- Base según filtros (categoría usa su propia tabla) ---
const usaCat = catSel !== '';
const campos = usaCat ? camposCat : camposEst;
const base = usaCat
  ? cat.filter(r => String(r.categoria).toLowerCase() === catSel)
  : est.filter(r => !estadoSel || String(r.estado).toUpperCase() === estadoSel);

const anios = anioSel === 'Todos' ? [2016, 2017, 2018] : [Number(anioSel)];
const periodo = base.filter(r => anios.includes(Number(r.year)));

// --- Resultados ---
const resumen = elegir(kpis(sumar(periodo, campos)));

const por_anio = {};
for (const a of [2016, 2017, 2018]) {
  const rows = base.filter(r => Number(r.year) === a);
  if (rows.length) por_anio[a] = elegir(kpis(sumar(rows, campos)));
}

const por_mes = Object.entries(agrupar(
    periodo.map(r => ({ ...r, ym: `${r.year}-${String(r.month).padStart(2, '0')}` })), 'ym'))
  .sort(([a], [b]) => a.localeCompare(b))
  .filter(([, rows]) => sumar(rows, campos).ordenes >= 20)   // quita meses con muy pocas órdenes
  .map(([ym, rows]) => ({ mes: ym, ...elegir(kpis(sumar(rows, campos))) }));

// Problemas: rankings dentro del periodo (ignoran el filtro de estado/categoría)
const estPeriodo = est.filter(r => anios.includes(Number(r.year)));
const catPeriodo = cat.filter(r => anios.includes(Number(r.year)));

const estados_mas_tarde = Object.entries(agrupar(estPeriodo, 'estado'))
  .map(([e, rows]) => { const t = sumar(rows, camposEst);
    return { estado: e, entregadas: t.entregadas, pct_tarde: div(100 * t.entregas_tarde, t.entregadas, 1) }; })
  .filter(x => x.entregadas >= 100)
  .sort((a, b) => b.pct_tarde - a.pct_tarde)
  .slice(0, 5);

const categorias_peor_calificadas = Object.entries(agrupar(catPeriodo, 'categoria'))
  .map(([c, rows]) => { const t = sumar(rows, camposCat);
    return { categoria: c || 'sin_categoria', resenas: t.resenas,
             calificacion: div(t.suma_calificacion, t.resenas),
             pct_negativas: div(100 * t.resenas_negativas, t.resenas, 1) }; })
  .filter(x => x.resenas >= 50)
  .sort((a, b) => a.calificacion - b.calificacion)
  .slice(0, 5);

// --- Liga al reporte filtrado ---
const filtrosUrl = [];
if (!usaCat && estadoSel) filtrosUrl.push(`customers/customer_state eq '${estadoSel}'`);
if (usaCat) filtrosUrl.push(`products/category eq '${catSel}'`);
if (anioSel !== 'Todos') filtrosUrl.push(`calendar/year eq ${anioSel}`);
const liga_reporte = REPORT_URL +
  (filtrosUrl.length ? '?filter=' + encodeURIComponent(filtrosUrl.join(' and ')) : '');

return [{ json: {
  filtros: {
    estado: usaCat ? '(no aplica con categoría)' : (estadoSel || 'Todos'),
    anio: anioSel,
    categoria: catSel || 'Todas',
  },
  tipo,
  pregunta: f['Pregunta'] || '',
  correo: f['Correo'],
  kpis_solicitados: kpisSel,
  fecha_corte: est[0]?.fecha_corte || '',
  nota: usaCat ? 'Con filtro de categoría no hay datos de entregas (% tarde, días) ni filtro por estado.' : '',
  sin_datos: periodo.length === 0,
  liga_reporte,
  datos: { resumen, por_anio, por_mes, estados_mas_tarde, categorias_peor_calificadas },
} }];
